// 1. Bugünün tarihini al (Istanbul saatine göre)
const now = new Date(new Date().toLocaleString("en-US", {timeZone: "Europe/Istanbul"}));
const todayDay = now.getDate();
const todayMonth = now.getMonth();
const todayYear = now.getFullYear();

const todayDisplay = new Intl.DateTimeFormat('tr-TR', {
  day: 'numeric', month: 'long', year: 'numeric'
}).format(now);

const allItems = $input.all();

// Yardımcı fonksiyon: Sütun ismini bul
function getField(obj, fieldName) {
  const lower = fieldName.toLowerCase();
  const key = Object.keys(obj).find(k => k.toLowerCase() === lower);
  return key ? obj[key] : undefined;
}

const appointments = allItems.filter(item => {
  const row = item.json;
  const status = getField(row, 'status');
  const dateTimeRaw = getField(row, 'dateTime') || getField(row, 'datetime') || getField(row, 'date');

  if (!status || !dateTimeRaw) return false;

  const isApproved = String(status).toLowerCase().trim() === 'approved';

  // Tarihi parse et
  const d = new Date(dateTimeRaw);
  if (isNaN(d.getTime())) return false;

  // SADECE GÜN-AY-YIL KARŞILAŞTIRMASI (Sayısal olarak)
  const isToday = d.getDate() === todayDay && 
                  d.getMonth() === todayMonth && 
                  d.getFullYear() === todayYear;

  return isApproved && isToday;
}).sort((a, b) => {
  const da = new Date(getField(a.json, 'dateTime') || getField(a.json, 'datetime'));
  const db = new Date(getField(b.json, 'dateTime') || getField(b.json, 'datetime'));
  return da.getTime() - db.getTime();
});

if (appointments.length === 0) {
  return [{ json: { hasAppointments: false, count: 0, todayDisplay, tableRows: '' } }];
}

// Tablo oluşturma
const tableRows = appointments.map((item, i) => {
  const row = item.json;
  const d = new Date(getField(row, 'dateTime') || getField(row, 'datetime'));
  const saat = d.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit', hour12: false });
  const name = getField(row, 'name') || '-';
  const email = getField(row, 'email') || '-';
  const bg = i % 2 === 0 ? '#f8fafc' : 'white';

  return `<tr style='background:${bg}'>`
    + `<td style='padding:12px 16px;font-weight:700;color:#0369a1;'>${saat}</td>`
    + `<td style='padding:12px 16px;font-weight:600;color:#1e293b'>${name}</td>`
    + `<td style='padding:12px 16px;color:#64748b;font-size:13px'>${email}</td>`
    + `</tr>`;
}).join('');

return [{ json: { hasAppointments: true, count: appointments.length, todayDisplay, tableRows } }];

// ── DEBUG: Sheets'ten gelen ilk satırın yapısını göster ──────────────────────

const allItems = $input.all();

if (allItems.length > 0) {

console.log('[GünlükÖzet] Toplam satır:', allItems.length);

console.log('[GünlükÖzet] İlk satır ham keys:', Object.keys(allItems[0].json));

console.log('[GünlükÖzet] İlk satır değerleri:', JSON.stringify(allItems[0].json, null, 2));

} else {

console.log('[GünlükÖzet] Sheets\'ten HİÇ satır gelmedi!');

}



// ── Yardımcı: objedeki anahtarı büyük/küçük harften bağımsız bul ─────────────

function getField(obj, fieldName) {

const lower = fieldName.toLowerCase();

const key = Object.keys(obj).find(k => k.toLowerCase() === lower);

return key ? obj[key] : undefined;

}



// ── Tarih ayrıştırma — Sheets formatlarını tolere eder ───────────────────────

// Sheets'ten gelen olası formatlar:

// ISO: "2025-04-22T10:00:00.000Z"

// Türkçe tarih: "22 Nisan 2025 10:00" (nadir, ama olur)

// Sadece sayı (Excel seri): 45769 ← bu durumda hata loglanır

function parseDate(raw) {

if (!raw) return null;

const str = String(raw).trim();

// ISO veya standart formatlar

const d = new Date(str);

if (!isNaN(d.getTime())) return d;

// "DD.MM.YYYY HH:mm" formatı (Google Sheets Türkçe locale)

const dotFmt = str.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})\s+(\d{1,2}):(\d{2})/);

if (dotFmt) {

const [, dd, mm, yyyy, hh, min] = dotFmt;

return new Date(`${yyyy}-${mm.padStart(2,'0')}-${dd.padStart(2,'0')}T${hh.padStart(2,'0')}:${min}:00`);

}

console.log('[GünlükÖzet] Tarih ayrıştırılamadı:', raw);

return null;

}



// ── Bugünün tarihini Istanbul'da hesapla ─────────────────────────────────────

const todayObj = new Date();

const todayISO = new Intl.DateTimeFormat('en-CA', {

timeZone: 'Europe/Istanbul'

}).format(todayObj);



const todayDisplay = new Intl.DateTimeFormat('tr-TR', {

day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Istanbul'

}).format(todayObj);



console.log('[GünlükÖzet] Bugün (Istanbul):', todayISO);



// ── Filtreleme ────────────────────────────────────────────────────────────────

const appointments = allItems

.filter(item => {

const row = item.json;

const status = getField(row, 'status');

const dateTime = getField(row, 'dateTime') ?? getField(row, 'datetime') ?? getField(row, 'date');



if (!status || !dateTime) {

console.log('[GünlükÖzet] Eksik alan — status:', status, '| dateTime:', dateTime,

'| keys:', Object.keys(row).join(', '));

return false;

}



const isApproved = String(status).toLowerCase().trim() === 'approved';

const d = parseDate(dateTime);

if (!d) return false;



const appointmentISODate = new Intl.DateTimeFormat('en-CA', {

timeZone: 'Europe/Istanbul'

}).format(d);



console.log('[GünlükÖzet] Satır kontrol —', status, '/', appointmentISODate, '— eşleşiyor:', isApproved && appointmentISODate === todayISO);

return isApproved && appointmentISODate === todayISO;

})

.sort((a, b) => {

const da = parseDate(getField(a.json, 'dateTime') ?? getField(a.json, 'datetime'));

const db = parseDate(getField(b.json, 'dateTime') ?? getField(b.json, 'datetime'));

return (da?.getTime() ?? 0) - (db?.getTime() ?? 0);

});



console.log('[GünlükÖzet] Filtreyi geçen randevu sayısı:', appointments.length);



if (appointments.length === 0) {

return [{ json: { hasAppointments: false, count: 0, todayDisplay, tableRows: '' } }];

}
